from collections import deque

def transform(grid):
    h, w = len(grid), len(grid[0])
    zeros = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 0]
    twos = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 2]
    if not zeros:
        return [row[:] for row in grid]

    sr = min(r for r, c in zeros)
    sc = min(c for r, c in zeros)
    nr = max(r for r, c in zeros) - sr + 1
    nc = max(c for r, c in zeros) - sc + 1
    start = (sr, sc)

    valid = set()
    for r in range(h - nr + 1):
        for c in range(w - nc + 1):
            if all(grid[i][j] != 3
                   for i in range(r, r + nr)
                   for j in range(c, c + nc)):
                valid.add((r, c))

    valid.add(start)
    dist = {start: 0}
    queue = deque([start])
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    while queue:
        r, c = queue.popleft()
        for dr, dc in directions:
            nxt = (r + dr, c + dc)
            if nxt in valid and nxt not in dist:
                dist[nxt] = dist[(r, c)] + 1
                queue.append(nxt)

    goal = None
    if twos:
        goal = (min(r for r, c in twos), min(c for r, c in twos))

    if goal in dist:
        dest = goal
    else:
        endpoints = []
        for r, c in dist:
            degree = sum((r + dr, c + dc) in dist for dr, dc in directions)
            if degree <= 1:
                endpoints.append((r, c))
        candidates = endpoints or list(dist)
        dest = max(candidates, key=lambda p: dist[p])

    out = [row[:] for row in grid]
    for r, c in zeros:
        out[r][c] = 1
    for r in range(dest[0], dest[0] + nr):
        for c in range(dest[1], dest[1] + nc):
            out[r][c] = 0
    return out
